const panel=$('#biz-panel');function toggleBiz(open){panel.hidden=!open;$('#biz-launch').setAttribute('aria-expanded',open);if(open)$('#biz-close').focus();else $('#biz-launch').focus()}$('#biz-launch').onclick=()=>toggleBiz(panel.hidden);$('#biz-close').onclick=()=>toggleBiz(false);const advice={sales:{n:0,text:'Start by mapping enquiry intake, qualification and the follow-up handoff. A useful first scope is an agent that prepares a qualified lead record and a draft response for review.'},ops:{n:1,text:'Identify one recurring task and its inputs, validation rules and exceptions. A useful first scope is extraction and validation, with a person reviewing uncertain records.'},knowledge:{n:2,text:'Identify the documents people search most often. A useful first scope is a knowledge agent that retrieves relevant information and cites its sources.'}};let bizService=0;$$('[data-biz]').forEach(b=>b.onclick=()=>{const d=advice[b.dataset.biz];bizService=d.n;$('#biz-answer').textContent=d.text;$$('[data-biz]').forEach(el=>el.classList.toggle('selected',el===b))});$('#biz-cta').onclick=e=>{e.preventDefault();toggleBiz(false);preselect(bizService)};
