function createTerminalRun(total){if(!Number.isInteger(total)||total<1)throw new Error('Invalid sample count');let stage=0;return {next(){if(stage<5)stage++;const processed=stage<3?0:stage===3?Math.ceil(total*.5):total;return {stage,processed,queued:total-processed,percent:stage*20,complete:stage===5}},snapshot(){const processed=stage<3?0:stage===3?Math.ceil(total*.5):total;return {stage,processed,queued:total-processed,percent:stage*20,complete:stage===5}}};}
const terminalScenarios={revenue:{count:12,noun:'sample leads',lines:['Captured 12 enquiries. Duplicates checked.','Attached sample account context and CRM fields.','Qualified 6 leads against demo routing rules.','Prepared 12 lead records. Responses held for human review.','Handoff ready. 12 records prepared; nothing sent.']},operations:{count:8,noun:'sample documents',lines:['Received 8 sample documents. Input checks passed.','Matched document fields to a demo reporting template.','Validated 4 documents against sample rules.','Prepared 8 structured records. Exceptions routed to review.','Report ready for review. No external systems updated.']},knowledge:{count:6,noun:'sample questions',lines:['Received 6 sample questions. Search scope defined.','Retrieved context from the simulated knowledge base.','Prepared 3 answers with sample source references.','Prepared 6 answers. Human review checkpoint added.','Answer pack ready. No real business documents accessed.']}};
let terminalKey='revenue',terminalMachine=createTerminalRun(12),terminalTimer=null,terminalRunning=false,terminalStarted=false,terminalBeat=0,terminalAnnounced=-1;
function terminalLog(text,kind='SYS',className=''){const line=document.createElement('p');line.className='log-line '+className;const tag=document.createElement('span');tag.textContent=kind;line.append(tag,document.createTextNode(text));$('#terminal-log').append(line);while($('#terminal-log').children.length>30)$('#terminal-log').firstElementChild.remove();$('#terminal-log').scrollTop=$('#terminal-log').scrollHeight;}
function stopTerminal(){if(terminalTimer!==null){clearTimeout(terminalTimer);terminalTimer=null}terminalRunning=false;}
const terminalStageLabels=['INTAKE','CONTEXT','DECIDE','REVIEW','READY'];
const terminalSubtasks={revenue:[['Reading enquiry payloads…','Checking fields and duplicates…','Building the intake queue…'],['Looking up sample accounts…','Matching CRM context…','Attaching account records…'],['Checking qualification criteria…','Scoring fit against sample rules…','Routing qualified leads…'],['Preparing lead records…','Drafting follow-up notes…','Adding human approval gates…'],['Assembling the handoff…','Checking review requirements…','Packaging the next actions…']],operations:[['Reading sample documents…','Checking document formats…','Preparing extraction queue…'],['Loading the report template…','Matching document fields…','Attaching source references…'],['Checking validation rules…','Flagging uncertain fields…','Preparing structured values…'],['Organising extracted records…','Routing exceptions…','Adding human review gates…'],['Assembling the draft report…','Checking source references…','Packaging review records…']],knowledge:[['Reading sample questions…','Defining the search scope…','Preparing the query queue…'],['Searching sample sources…','Matching relevant passages…','Attaching sample citations…'],['Comparing retrieved context…','Preparing grounded answers…','Checking source coverage…'],['Organising answer drafts…','Marking uncertain answers…','Adding human review gates…'],['Assembling the answer pack…','Checking citation coverage…','Preparing review handoff…']]};
function terminalDisplayProgress(state,beat,total){const fraction=Math.min(3,Math.max(0,beat))/4;const nextProcessed=state.stage<2?0:state.stage===2?Math.ceil(total*.5):total;const processed=Math.round(state.processed+(nextProcessed-state.processed)*fraction);return {...state,processed,queued:total-processed,percent:state.complete?100:Math.round(state.stage*20+fraction*20)}}
function renderTerminal(state,status){const display=terminalDisplayProgress(state,terminalBeat,terminalScenarios[terminalKey].count);const numbers=[['#terminal-processed',String(display.processed).padStart(2,'0')],['#terminal-queue',String(display.queued).padStart(2,'0')],['#terminal-checks',state.stage+'/5']];numbers.forEach(([selector,text])=>{const el=$(selector);if(el.textContent!==text){el.textContent=text;el.classList.remove('bump');requestAnimationFrame(()=>el.classList.add('bump'))}});$$('[data-stage]').forEach((el,i)=>{el.classList.toggle('done',i<state.stage);el.classList.toggle('active',i===state.stage&&!state.complete&&terminalStarted)});$('.terminal-progress').setAttribute('aria-valuenow',display.percent);$('.terminal-progress i').style.width=display.percent+'%';$('#terminal-percent').textContent=display.percent+'%';$('#terminal-status').textContent=status;$('#terminal-run').firstChild.textContent=state.complete?'Run again ':terminalRunning?'Pause ':terminalStarted?'Resume ':'Run workflow ';$('#terminal-run span').textContent=terminalRunning?'Ⅱ':'▶';$('#terminal-step').disabled=state.complete;$('.terminal').classList.toggle('executing',terminalRunning);$('#terminal-stage-name').textContent=state.complete?'ALL STAGES COMPLETE':terminalStarted?`STAGE ${state.stage+1} / 5 · ${terminalStageLabels[state.stage]}`:'AWAITING INPUT';$('#terminal-stage-percent').textContent=state.complete?'100%':terminalStarted?terminalBeat*25+'%':'—';$('#terminal-activity-text').textContent=state.complete?'Ready for human review. Nothing sent.':terminalStarted?terminalSubtasks[terminalKey][state.stage][Math.max(0,terminalBeat-1)]:'Choose a workflow to begin.';}
function announceTerminalStage(){const stage=terminalMachine.snapshot().stage;if(stage<5&&terminalAnnounced!==stage){terminalAnnounced=stage;terminalLog(`Starting ${terminalStageLabels[stage].toLowerCase()} process…`,String(stage+1).padStart(2,'0'),'command')}}
function resetTerminal(key=terminalKey){stopTerminal();terminalKey=key;terminalStarted=false;terminalBeat=0;terminalAnnounced=-1;const d=terminalScenarios[key];terminalMachine=createTerminalRun(d.count);$$('[data-terminal]').forEach(b=>{const on=b.dataset.terminal===key;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});$('.screen-heading>span:first-child').textContent='ezydrag://workflow/'+key;$('#terminal-input').placeholder='run '+key;$('#terminal-log').replaceChildren();terminalLog(`Sandbox initialised. ${d.count} ${d.noun} queued.`);terminalLog('Type “run” or hit Run workflow to begin.');renderTerminal(terminalMachine.snapshot(),'READY');}
