$$('[data-terminal]').forEach(b=>b.onclick=()=>resetTerminal(b.dataset.terminal));$('#terminal-run').onclick=runTerminal;$('#terminal-step').onclick=()=>{stopTerminal();advanceTerminal()};$('#terminal-reset').onclick=()=>resetTerminal();$('#terminal-command').onsubmit=e=>{e.preventDefault();const value=$('#terminal-input').value.trim().toLowerCase();$('#terminal-input').value='';if(!value)return;terminalLog('❯ '+value,'CMD','command');const parts=value.split(/\s+/);if(parts[0]==='help'){terminalLog('Commands: run [revenue|operations|knowledge], pause, resume, step, reset, help.');return}if(parts[0]==='run'){if(parts.length>2||(parts[1]&&!Object.hasOwn(terminalScenarios,parts[1]))){terminalLog('Choose revenue, operations or knowledge.','ERR');return}if(parts[1])resetTerminal(parts[1]);if(!terminalRunning)runTerminal();return}if(parts.length!==1){terminalLog('Unknown command. Type “help” for supported commands.','ERR');return}if(value==='reset'){resetTerminal();return}if(value==='step'){stopTerminal();advanceTerminal();return}if(value==='pause'){stopTerminal();renderTerminal(terminalMachine.snapshot(),terminalMachine.snapshot().complete?'REVIEW READY':terminalStarted?'PAUSED':'READY');return}if(value==='resume'){if(!terminalRunning)runTerminal();return}terminalLog('Unknown command. Type “help” for supported commands.','ERR');};
